import type { PerformanceAndBreakdownWaterfallData } from '../../types';
import { getPerformanceAndBreakdownBrandImage } from '../assets/brandImageUrls';
import { buildPerformanceAndBreakdownDeepDiveDrillComparisonLines } from './deepDiveLayerComparisonLines';
import {
  buildPerformanceAndBreakdownDeepDiveImagesData,
  PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX,
} from './deepDiveWaterfallPrefix';

const PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_SUB_BRAND_VALUES = [
  1.2, 0.9, 0.6, 0.4,
] as const;

function buildGenericSubBrandLabels(brandName: string): readonly string[] {
  return [
    brandName,
    `${brandName} - NA`,
    `${brandName} Extra`,
    `${brandName} - Others`,
  ];
}

export function buildPerformanceAndBreakdownDeepDiveSubBrandMock(
  brandName: string,
): PerformanceAndBreakdownWaterfallData {
  const subBrandLabels = buildGenericSubBrandLabels(brandName);
  const subBrandValues =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_SUB_BRAND_VALUES.slice(
      0,
      subBrandLabels.length,
    );
  const le =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.values[2] +
    subBrandValues.reduce((sum, value) => sum + value, 0);
  const lastIndex =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length +
    subBrandLabels.length;
  const columnCount = lastIndex + 1;
  const brandImage = getPerformanceAndBreakdownBrandImage(brandName);

  return {
    values: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.values,
      ...subBrandValues,
      le,
    ],
    labels: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels,
      ...subBrandLabels,
      "'26 LE",
    ],
    formattedData: [
      [
        ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.formatted,
        ...subBrandValues.map((value) => `+${value}`),
        le.toFixed(1),
      ],
    ],
    specialIndexes: { first: 0, last: lastIndex },
    disabledIndexes: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.disabledIndexes,
      lastIndex,
    ],
    clickableIndexes: Array.from(
      { length: subBrandLabels.length },
      (_, index) =>
        PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length +
        index,
    ),
    filterValues: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.filterValues,
      ...subBrandLabels,
      null,
    ],
    images: {
      data: buildPerformanceAndBreakdownDeepDiveImagesData(
        brandImage,
        subBrandLabels,
      ),
    },
    comparisonLine: {
      data: buildPerformanceAndBreakdownDeepDiveDrillComparisonLines(
        columnCount,
      ),
    },
  };
}

/** Brahma fixture for tests and default sub_brand map entry. */
export const PerformanceAndBreakdownDeepDiveSubBrandWaterfallMock =
  buildPerformanceAndBreakdownDeepDiveSubBrandMock('Brahma');
